page_limit=20
while True:
    page = apis.phone.search_contacts(access_token=phone_token, query='', relationship='friend', page_index=page_index, page_limit=page_limit)
    if not page:
        break
    friend_contacts.extend(page)
    page_index += 1
friend_set = set((c.get('email') or '').lower() for c in friend_contacts if c.get('email'))
friend_set = {e for e in friend_set if e}
print('friend_set_count', len(friend_set))
print('friend_set_sample', sorted(list(friend_set))[:5])

# Previously computed ids
ids_to_star = [2850, 7101, 7599]
ids_to_unstar = [3066, 6209, 29483]

# Verification using show_thread: friend involvement if any sender/recipient email in emails list matches friend_set

def thread_friend_hits_show_thread(thread):
    friend_hits=set()
    # emails list
    for em in (thread.get('emails') or []):
        s = (em.get('sender') or {}).get('email')
        if s:
            s=s.lower()
            if s in friend_set:
                friend_hits.add(s)
        for r in (em.get('recipients') or []):
            re = (r.get('email') if isinstance(r, dict) else None)
            if re:
                re=re.lower()
                if re in friend_set:
                    friend_hits.add(re)
    # drafts recipients? exclude drafts
    return sorted(friend_hits)

# Fetch threads and show statuses

def verify_ids(ids):
    rows=[]
    for tid in ids:
        th = apis.gmail.show_thread(access_token=gmail_token, email_thread_id=tid)
        rows.append({
            'email_thread_id': tid,
            'archived': th.get('archived'),
            'starred': th.get('starred'),
            'friend_hits': thread_friend_hits_show_thread(th),
            'first_subject': (th.get('emails') or [{}])[0].get('subject') if th.get('emails') else None,
            'emails_count': len(th.get('emails') or [])
        })
    return rows

